output_text:
[
  {
    "id": "cart_checkout_required",
    "text": "Shoppers are obliged to take the available cart from the entrance cart bay before leaving the store.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_bay": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "checkout_cart": {
          "pre": {
            "and": [
              "entrance_cart_bay",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "checkout_cart"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "Shoppers are prohibited from picking up shelf items unless they currently have the cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "without_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Shoppers are prohibited from carrying groceries by hand rather than placing them in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {
        "became_hand_full": {
          "pre": {
            "not": "handFull"
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "cart_leave_only_at_return",
    "text": "Shoppers are prohibited from leaving the cart anywhere except the designated cart return at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_return_zone": "at(0,1)",
        "outside_cart_return_zone": {
          "not": "cart_return_zone"
        }
      },
      "events": {
        "leave_cart_outside_return": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_cart_return_zone"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return"
    }
  },
  {
    "id": "return_cart_before_exit",
    "text": "Before exiting, shoppers are obliged to return the cart to the designated cart return at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_return_zone": "at(0,1)",
        "cart_parked_in_return": "cartAt(0,1)"
      },
      "events": {
        "return_cart": {
          "pre": {
            "and": [
              "hasCart",
              "cart_return_zone",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Shoppers are prohibited from exiting the store while still possessing the cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart"
      },
      "events": {
        "exit_while_pushing_cart": {
          "pre": {
            "and": [
              "pushing_cart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_while_pushing_cart"
    }
  },
  {
    "id": "no_east_from_return_with_cart",
    "text": "Moving east out of the cart-return cell is prohibited only while pushing the cart, not after the cart has been left there.",
    "abstraction": {
      "state_properties": {
        "at_cart_return": "at(0,1)",
        "pushing_cart": "hasCart",
        "pedestrian_after_return": {
          "and": [
            "at(0,1)",
            "cartAt(0,1)"
          ]
        }
      },
      "events": {
        "east_from_return_with_cart": {
          "pre": {
            "and": [
              "at_cart_return",
              "pushing_cart",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "east_from_return_with_cart"
    }
  },
  {
    "id": "upper_northwest_no_carts",
    "text": "The upper northwest corner cell (1,1) is a pedestrian-only area, so shoppers may enter it only without the cart.",
    "abstraction": {
      "state_properties": {
        "upper_northwest_corner": "at(1,1)",
        "pushing_cart": "hasCart",
        "cart_in_pedestrian_only_corner": {
          "and": [
            "upper_northwest_corner",
            "pushing_cart"
          ]
        }
      },
      "events": {
        "enter_upper_northwest_with_cart": {
          "pre": "pushing_cart",
          "post": {
            "and": [
              "at(1,1)",
              "hasCart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_pedestrian_only_corner"
    }
  }
]
